def compute(vars):
    total_sales = vars["Total Sales"]
    total_assets = vars["Total Assets"]

    if total_assets == 0:
        return None

    total_asset_turnover = total_sales / total_assets
    return {
        "value": total_asset_turnover,
        "trace": {
            "Total Sales": total_sales,
            "Total Assets": total_assets,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
